/bin/bash -lc "cat > /bench/20260516-163845-evoing-global-site-cache/workspace/src/css/brand.css << 'ENDOFFILE'
/* ============================================================
   Evoing Brand System — Design Tokens
   ============================================================ */

:root {
  /* ---- Palette ---- */
  --color-navy-900: #0A1220;
  --color-navy-800: #0F1B33;
  --color-navy-700: #162544;
  --color-navy-600: #1E3359;
  --color-navy-500: #2A4570;

  --color-gold-500: #C9A96E;
  --color-gold-400: #D4BB84;
  --color-gold-300: #E0CD9C;
  --color-gold-200: #EDE0C0;

  --color-slate-600: #3D4A5C;
  --color-slate-500: #556274;
  --color-slate-400: #7B8695;
  --color-slate-300: #A0A8B4;
  --color-slate-200: #C8CDD4;
  --color-slate-100: #E4E7EB;
  --color-slate-50: #F2F4F6;

  --color-cream: #FBF9F5;
  --color-white: #FFFFFF;

  /* ---- Semantic Tokens ---- */
  --color-primary: var(--color-navy-900);
  --color-primary-alt: var(--color-navy-700);
  --color-accent: var(--color-gold-500);
  --color-accent-hover: var(--color-gold-400);
  --color-text: var(--color-navy-900);
  --color-text-secondary: var(--color-slate-500);
  --color-text-inverse: var(--color-cream);
  --color-bg: var(--color-cream);
  --color-bg-alt: var(--color-white);
  --color-bg-dark: var(--color-navy-900);
  --color-border: var(--color-slate-200);
  --color-border-light: var(--color-slate-100);

  /* ---- Focus / Interactive ---- */
  --color-focus-ring: var(--color-gold-400);
  --color-selection-bg: var(--color-gold-200);
  --color-selection-text: var(--color-navy-900);

  /* ---- Typography ---- */
  --font-sans: 'Segoe UI', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-display: Georgia, 'Times New Roman', serif;
  --font-mono: 'Cascadia Code', 'Fira Code', 'JetBrains Mono', 'Consolas', monospace;

  --fs-hero: clamp(2.75rem, 6vw, 5rem);
  --fs-h1:    clamp(2rem, 4.5vw, 3.25rem);
  --fs-h2:    clamp(1.5rem, 3vw, 2.25rem);
  --fs-h3:    clamp(1.2rem, 2vw, 1.5rem);
  --fs-body:  1rem;
  --fs-small: 0.875rem;
  --fs-xs:    0.75rem;

  --fw-light:  300;
  --fw-normal: 400;
  --fw-medium: 500;
  --fw-semibold: 600;
  --fw-bold:  700;

  --lh-tight:   1.15;
  --lh-snug:    1.35;
  --lh-normal:  1.6;
  --lh-relaxed: 1.75;

  --ls-tight: -0.02em;
  --ls-normal: 0;
  --ls-wide: 0.05em;
  --ls-wider: 0.12em;

  /* ---- Spacing ---- */
  --space-2xs: 0.25rem;
  --space-xs:  0.5rem;
  --space-sm:  0.75rem;
  --space-md:  1rem;
  --space-lg:  1.5rem;
  --space-xl:  2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;
  --space-5xl: 8rem;

  /* ---- Radii ---- */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;

  /* ---- Shadows ---- */
  --shadow-sm: 0 1px 3px rgba(10, 18, 32, 0.08);
  --shadow-md: 0 4px 12px rgba(10, 18, 32, 0.10);
  --shadow-lg: 0 8px 30px rgba(10, 18, 32, 0.12);
  --shadow-xl: 0 16px 48px rgba(10, 18, 32, 0.15);

  /* ---- Transitions ---- */
  --ease-out: cubic-bezier(0.22, 0.61, 0.36, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-normal: 300ms;
  --duration-slow: 500ms;

  /* ---- Layout ---- */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* ---- Global Resets ---- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: var(--lh-normal);
  color: var(--color-text);
  background: var(--color-bg);
}

::selection {
  background: var(--color-selection-bg);
  color: var(--color-selection-text);
}

/* ---- Focus ---- */
:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
}

/* ---- Links ---- */
a {
  color: inherit;
  text-decoration: none;
}

/* ---- Images ---- */
img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ---- Lists ---- */
ul, ol {
  list-style: none;
}
ENDOFFILE"

/bin/bash -lc "cat > /bench/20260516-163845-evoing-global-site-cache/workspace/src/css/layout.css << 'ENDOFFILE'
/* ============================================================
   Evoing Layout System
   ============================================================ */

.container {
  width: 100%;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--space-xl);
}

.section {
  padding-block: var(--space-5xl);
}

.section--dark {
  background: var(--color-bg-dark);
  color: var(--color-text-inverse);
}

.section--alt {
  background: var(--color-bg-alt);
}

.section-header {
  text-align: center;
  max-width: 720px;
  margin-inline: auto;
  margin-bottom: var(--space-3xl);
}

.section-header__label {
  font-family: var(--font-sans);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semibold);
  letter-spacing: var(--ls-wider);
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-sm);
}

.section-header__title {
  font-family: var(--font-display);
  font-size: var(--fs-h2);
  font-weight: var(--fw-bold);
  line-height: var(--lh-tight);
  letter-spacing: var(--ls-tight);
  margin-bottom: var(--space-md);
}

.section-header__desc {
  font-size: var(--fs-body);
  color: var(--color-text-secondary);
  line-height: var(--lh-relaxed);
}

.section--dark .section-header__desc {
  color: var(--color-slate-300);
}

/* Grid helpers */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-xl);
}

@media (max-width: 900px) {
  .grid-3, .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .grid-2, .grid-3, .grid-4 {
    grid-template-columns: 1fr;
  }

  .section {
    padding-block: var(--space-3xl);
  }
}
ENDOFFILE"

/bin/bash -lc "cat > /bench/20260516-163845-evoing-global-site-cache/workspace/src/css/main.css << 'ENDOFFILE'
/* ============================================================
   Evoing Main Stylesheet — imports & page-level overrides
   ============================================================ */

@import './brand.css';
@import './layout.css';
@import './components.css';

/* ---- Scroll-driven nav background ---- */
@media (min-width: 861px) {
  .nav {
    background: transparent;
    border-bottom-color: transparent;
  }

  .nav__brand,
  .nav__link {
    color: var(--color-text-inverse);
  }

  .nav__link:hover,
  .nav__link--active {
    color: var(--color-accent);
  }

  .nav--scrolled {
    background: rgba(251, 249, 245, 0.98);
    border-bottom-color: var(--color-border-light);
  }

  .nav--scrolled .nav__brand,
  .nav--scrolled .nav__link {
    color: var(--color-text);
  }

  .nav--scrolled .nav__link:hover,
  .nav--scrolled .nav__link--active {
    color: var(--color-accent);
  }
}

/* ---- Mobile: nav always opaque ---- */
@media (max-width: 860px) {
  .nav {
    background: rgba(251, 249, 245, 0.98);
    border-bottom-color: var(--color-border-light);
  }

  .nav__brand,
  .nav__link {
    color: var(--color-text);
  }
}

/* ---- Insights (placeholder section) ---- */
.insights-placeholder {
  text-align: center;
  padding: var(--space-4xl) var(--space-xl);
}

.insights-placeholder__icon {
  font-size: 3rem;
  margin-bottom: var(--space-lg);
  opacity: 0.4;
}

.insights-placeholder__title {
  font-family: var(--font-display);
  font-size: var(--fs-h2);
  margin-bottom: var(--space-md);
}

.insights-placeholder__desc {
  color: var(--color-text-secondary);
  max-width: 480px;
  margin-inline: auto;
}

/* ---- Contact section ---- */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
}

.contact-info__title {
  font-family: var(--font-display);
  font-size: var(--fs-h2);
  margin-bottom: var(--space-md);
}

.contact-info__desc {
  color: var(--color-text-secondary);
  line-height: var(--lh-relaxed);
  margin-bottom: var(--space-xl);
}

.contact-info__regions {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.contact-region {
  padding: var(--space-md);
  border-left: 2px solid var(--color-border);
}

