    ]);

    /* Animate stats counters on scroll */
    const stats = document.querySelectorAll('.stat-item__value');
    if (stats.length > 0) {
      const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.style.animation = 'fadeIn 0.6s ease-out forwards';
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.5 });
      stats.forEach((el) => { el.style.opacity = '0'; observer.observe(el); });
    }

    /* Reveal cards on scroll */
    const cards = document.querySelectorAll('.card, .case-card, .region-card, .leader-card, .insight-card, .methodology-step');
    if (cards.length > 0) {
      const cardObserver = new IntersectionObserver((entries) => {
