// --- 6. Business rules ---
console.log('\\n6. Business rules');
const capIds = caps.map((c) => c.id);
const indIds = inds.map((i) => i.id);
const regionIds = regs.map((r) => r.id);

// Service catalog references valid capabilities
svcCat.forEach((ce) => {
