});

// Insights reference valid categories and regions
const validRegions = ['"'global', 'apac', 'emea', 'amer'];
insights.forEach((ins) => {
  assert(capIds.includes(ins.category) || ins.category === 'strategy-advisory', "'`insight ${ins.id} category valid`);
  assert(validRegions.includes(ins.region), `insight ${ins.id} region valid`);
});

// Leadership references valid regions
leaders.forEach((l) => {
  assert(regionIds.includes(l.region) || l.region === '"'global', "'`leader ${l.id} region valid`);
});

// Nav items must reference existing HTML sections
const navIds = nav.primary.map((n) => n.id);
for (const nid of navIds) {
  assert(html.includes(`id="${nid}"`), `nav item ${nid} has matching HTML section`);
}

// --- 7. Server ---
console.log('"'\\n7. Server startup');
const serverJS = await readText('server.mjs');
assert(serverJS.includes('0.0.0.0'), 'server binds to 0.0.0.0');
assert(serverJS.includes('5173'), 'server uses port 5173');

// --- 8. Package scripts ---
console.log('\\n8. Package scripts');
const pkg = await readJson('package.json');
assert(pkg.scripts && pkg.scripts.start && pkg.scripts.test, 'package.json has start and test scripts');

// --- 9. First-party line count ---
console.log('\\n9. First-party source lines');
async function countLines(relPath) {
  const text = await readText(relPath);
  return text.split('\\n').length;
}

const srcFiles = [
  'src/index.html',
  'src/css/brand.css', 'src/css/layout.css', 'src/css/components.css', 'src/css/main.css',
  'src/css/methodology.css', 'src/css/insights.css', 'src/css/industry-detail.css', 'src/css/leadership.css',
