  'src/data/leadership.json',
  'server.mjs', 'scripts/validate.mjs'
];

let totalLines = 0;
for (const f of srcFiles) {
  const lines = await countLines(f);
  totalLines += lines;
  console.log("'`  ${String(lines).padStart(5)}  ${f}`);
}
console.log(`  -----  ----------`);
console.log(`  ${String(totalLines).padStart(5)}  TOTAL first-party source lines`);

// --- Summary ---
console.log(`'"\\n=== Validation Summary ==="'`);
console.log(`  Checks: ${checks}`);
console.log(`  Passed: ${checks - failures}`);
console.log(`  Failed: ${failures}`);

if (totalLines < 10000) {
  console.log(`'"\\n  WARNING: first-party lines ("'${totalLines}) below 10,000 target.`);
}

if (failures > 0) {
  console.log('"'\\n  Validation FAILED.');
  process.exit(1);
} else {
  console.log('\\n  Validation PASSED.');
}
ENDOFFILE"

