/**
 * Evoing main entry — orchestrates modules, fetches data-driven sections.
 */
(function () {
  async function boot() {
    await Promise.all([
      renderSolutions(),
      renderServiceCatalog(),
      renderCaseStudies(),
      renderArticles(),
      renderOffices(),
      renderLeadership(),
      renderCareers(),
      embedIndustryDeepData()
    ]);

    /* Animate stats */
    const stats = document.querySelectorAll('.stat-item__value');
    if (stats.length > 0) {
      const obs = new IntersectionObserver((e) => { e.forEach((en) => { if (en.isIntersecting) { en.target.style.animation = 'fadeIn 0.6s ease-out forwards'; obs.unobserve(en.target); } }); }, { threshold: 0.5 });
      stats.forEach((el) => { el.style.opacity = '0'; obs.observe(el); });
    }

    /* Reveal cards */
    const cards = document.querySelectorAll('.card,.case-study-card,.region-card,.leader-card,.insight-card,.article-card,.office-card,.job-card,.solution-card,.methodology-step,.value-card,.path-card');
    if (cards.length > 0) {
      const co = new IntersectionObserver((e) => { e.forEach((en) => { if (en.isIntersecting) { en.target.style.animation = 'fadeInUp 0.5s ease-out forwards'; co.unobserve(en.target); } }); }, { threshold: 0.15, rootMargin: '0px 0px -30px 0px' });
      cards.forEach((el) => { el.style.opacity = '0'; el.style.transform = 'translateY(20px)'; co.observe(el); });
    }

    console.log('[Evoing] Global site ready.');
  }

  async function fetchJSON(path) {
    const resp = await fetch(path);
    if ("'!resp.ok) throw new Error(`Failed to load ${path}: ${resp.status}`);
    return resp.json();
  }

  function escHtml(s) { return String(s).replace(/&/g,'"'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;'); }

  async function renderSolutions() {
    const grid = document.getElementById('solutions-grid');
    const dataEl = document.getElementById('solutions-data');
    if ("'!grid || !dataEl) return;
    try {
