      dataEl.textContent = JSON.stringify(data);
      const lang = document.documentElement.lang || 'zh';
      const frag = document.createDocumentFragment();
      data.forEach((s) => {
        const card = document.createElement('article');
        card.className = 'solution-card';
        card.dataset.solutionId = s.id;
        card.dataset.caps = (s.relatedCapabilities || []).join(',');
        card.innerHTML =
          '<h3 class=\"solution-card__name\">' + escHtml(s.name[lang]) + '</h3>' +
          '<p class=\"solution-card__problem\">' + escHtml(s.problem[lang]) + '</p>' +
          '<div class=\"solution-card__modules\">' + (s.modules[lang] || []).map((m) => '<span class=\"solution-card__module\">' + escHtml(m) + '</span>').join('') + '</div>' +
          '<p class=\"solution-card__outcomes\">' + escHtml(s.outcomes[lang]) + '</p>' +
          '<div class=\"solution-card__metrics\">' + (s.metrics[lang] || []).slice(0,2).map((m) => '<span class=\"solution-card__metric\">' + escHtml(m) + '</span>').join('') + '</div>';
        frag.appendChild(card);
      });
      grid.innerHTML = '';
      grid.appendChild(frag);
    } catch (e) { console.warn('[Evoing] Solutions load failed:', e.message); }
  }

  async function renderServiceCatalog() {
    const grid = document.getElementById('service-grid');
    if ("'!grid) return;
    try {
      const catalog = await fetchJSON('"'data/service-catalog.json');
      const lang = document.documentElement.lang || 'zh';
      const frag = document.createDocumentFragment();
      catalog.forEach((ce) => { ce.offerings.forEach((o) => {
        const card = document.createElement('article');
